window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[7]={"id":"007","numero":7,"titre":"Droits individuels et collectifs du patient","objectifs":[{"id":"7-1","rang":"A","rubrique":"Définition","titre":"Connaître les droits individuels des patients","contenu":"<div class=\"callout callout-info\"><strong>Socle = loi du <span class=\"kw-chiffre\">4 mars 2002</span></strong> (dite <span class=\"kw-def\">loi Kouchner</span>, «&nbsp;droits des malades et qualité du système de santé&nbsp;»). Elle consacre les <span class=\"kw-def\">droits individuels</span> du patient et fait de l'acte de soin une <strong><span class=\"kw-def\">codécision</span></strong> : le médecin informe et préconise, le patient décide.</div>\n      <p>Principaux <span class=\"kw-def\">droits individuels</span> reconnus au patient :</p>\n      <ul>\n        <li><strong>Droit à l'<span class=\"kw-def\">information</span></strong> «&nbsp;loyale, claire et appropriée&nbsp;» sur son état et tous les actes proposés (le <span class=\"kw-def\">secret médical</span> n'est pas opposable au patient lui-même).</li>\n        <li><strong>Droit au <span class=\"kw-def\">consentement libre et éclairé</span></strong>, préalable à tout acte (intangibilité de la personne, art. 16 Code civil).</li>\n        <li><strong>Droit d'<span class=\"kw-def\">accès direct</span> à son <span class=\"kw-def\">dossier médical</span></strong> (art. L. 1111-7 CSP).</li>\n        <li><strong>Droit au respect de la <span class=\"kw-def\">vie privée</span></strong> et au <strong>contrôle de ses <span class=\"kw-def\">données de santé</span></strong> (rectification, opposition, restriction d'accès).</li>\n        <li><strong>Droit de désigner une <span class=\"kw-def\">personne de confiance</span></strong> (art. L. 1111-6 CSP) — accompagnement et témoignage de la volonté.</li>\n        <li><strong>Droit de <span class=\"kw-def\">refuser les soins</span></strong>, même au péril de sa vie, après information sur les conséquences.</li>\n        <li><strong>Droits en <span class=\"kw-clinique\">fin de vie</span></strong> : refus de l'<span class=\"kw-def\">obstination déraisonnable</span>, <span class=\"kw-def\">directives anticipées</span>, <span class=\"kw-def\">sédation profonde et continue</span> (lois du <span class=\"kw-chiffre\">22 avril 2005</span> et du <span class=\"kw-chiffre\">2 février 2016</span>).</li>\n      </ul>\n      <div class=\"obj-callout success\"><strong>Hiérarchie de la volonté</strong> (loi 2016) : <span class=\"kw-def\">directives anticipées</span> &gt; témoignage de la <span class=\"kw-def\">personne de confiance</span> &gt; témoignage de la famille / des proches.</div>\n      <p class=\"obj-source\"><em>Distillé depuis le Collège de Médecine légale (item 7).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 9 — Ethique et déontologie médicale · 1 — Relation médecin-malade</em></p>","frequence":0},{"id":"7-2","rang":"B","rubrique":"Définition","titre":"Connaître les droits collectifs des patients","contenu":"<div class=\"callout callout-info\"><strong><span class=\"kw-def\">Démocratie sanitaire</span>.</strong> Au-delà des droits individuels, la loi du <span class=\"kw-chiffre\">4 mars 2002</span> reconnaît des <span class=\"kw-def\">droits collectifs</span> : les usagers participent, via leurs représentants, au fonctionnement et aux choix du système de santé.</div>\n      <ul>\n        <li><strong><span class=\"kw-def\">Représentation des usagers</span></strong> : portée par des <span class=\"kw-def\">associations agréées</span> (<span class=\"kw-def\">agrément</span> national ou régional), siégeant dans les <span class=\"kw-def\">instances de santé</span> (conseils de <span class=\"kw-def\">surveillance</span> des établissements, agences, conférences).</li>\n        <li><strong><span class=\"kw-def\">Commission des usagers (CDU)</span></strong> dans chaque établissement public ou privé : informée des <span class=\"kw-clinique\">plaintes et réclamations</span> et de leurs suites, veille au respect des droits ; ses membres sont astreints au <span class=\"kw-def\">secret professionnel</span>.</li>\n        <li><strong>Voies de recours</strong> en cas de difficulté d'accès aux droits : <span class=\"kw-def\">médiateur-médecin</span>, <span class=\"kw-def\">CADA</span> (documents administratifs), <span class=\"kw-def\">Défenseur des droits</span>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Distillé depuis le Collège de Médecine légale (item 7) et les fiches sources (Commission des usagers).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 9 — Ethique et déontologie médicale · 8 — Discriminations</em></p>","frequence":0},{"id":"7-3","rang":"B","rubrique":"Définition","titre":"Savoir différencier droit et devoir des patients","contenu":"<div class=\"callout callout-info\"><strong>Symétrie droit / devoir.</strong> Au <strong>devoir d'information du médecin</strong> répond le <strong>droit du patient d'être informé</strong> ; à son <strong>droit de décider</strong> (codécision) répondent des <strong>devoirs</strong> de participation et de responsabilité.</div>\n      <ul>\n        <li><strong>Droits du patient</strong> : être <span class=\"kw-def\">informé</span>, <span class=\"kw-def\">consentir ou refuser</span>, <span class=\"kw-def\">accéder à son dossier</span>, voir sa <span class=\"kw-def\">vie privée</span> et son <span class=\"kw-def\">secret</span> protégés.</li>\n        <li><strong>Devoirs du patient</strong> : donner une <span class=\"kw-def\">information sincère</span> sur son état (un <span class=\"kw-def\">consentement</span> fondé sur une information erronée n'est pas valide, en miroir), <span class=\"kw-def\">participer à la décision</span>, respecter les règles de fonctionnement et les autres usagers / soignants.</li>\n        <li><strong>Responsabilité vis-à-vis d'autrui</strong> : la <span class=\"kw-def\">volonté de ne pas savoir</span> cesse de s'appliquer <span class=\"kw-alerte\">lorsque des tiers sont exposés à un risque de contamination</span> (ex. <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">tuberculose</span>) — intérêt de <span class=\"kw-def\">santé publique</span>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Distillé depuis le Collège de Médecine légale (item 7) et les fiches sources.</em></p>","frequence":0},{"id":"7-4","rang":"A","rubrique":"Définition","titre":"Connaître les grands principes de l’information médicale","contenu":"<p>L'<span class=\"kw-def\">information médicale</span> est la condition d'un <span class=\"kw-def\">consentement éclairé</span> valide. Elle doit être «&nbsp;<strong>loyale, claire et appropriée</strong>&nbsp;» : explicite et adaptée au niveau de compréhension du patient (loi du <span class=\"kw-chiffre\">4 mars 2002</span>).</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Contenu attendu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Étendue</strong></td><td><span class=\"kw-def\">État de santé</span> ; <span class=\"kw-def\">pronostic</span> ; <span class=\"kw-def\">traitements et investigations</span> proposés ; <span class=\"kw-def\">alternatives</span> ; <span class=\"kw-alerte\">risques encourus en cas de refus</span> ; <span class=\"kw-def\">conditions financières</span> de prise en charge</td></tr>\n          <tr><td><strong>Risques à révéler</strong></td><td>Risques <span class=\"kw-def\">fréquents</span> <strong>ET</strong> <span class=\"kw-alerte\">graves</span>, même exceptionnels (catalogue exhaustif impossible). «&nbsp;Graves&nbsp;» = <span class=\"kw-alerte\">décès</span>, <span class=\"kw-alerte\">invalidité</span>, risques esthétiques importants</td></tr>\n          <tr><td><strong>Forme</strong></td><td><strong><span class=\"kw-def\">Orale</span></strong>, lors d'un <span class=\"kw-clinique\">entretien individuel</span> préalable aux soins ; l'écrit n'est qu'un complément</td></tr>\n          <tr><td><strong>Preuve</strong></td><td>Charge sur le <strong>professionnel / l'établissement</strong> depuis l'<span class=\"kw-def\">arrêt Hédreul du 25 février 1997</span> (inversion de la charge de la preuve) ; par <span class=\"kw-def\">tous moyens</span> (faisceau de présomptions : traces dans le dossier, délais de réflexion, courriers, témoignages)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Exceptions au devoir d'information</strong> (jurisprudence) : <span class=\"kw-clinique\">urgence vitale</span> chez un patient non en état de la recevoir ; <span class=\"kw-def\">refus du patient d'être informé</span>. Mais l'information <strong>s'impose</strong> <span class=\"kw-alerte\">lorsque des tiers sont exposés à un risque de transmission</span> (ex. <span class=\"kw-etio\">VIH</span>).</div>\n      <div class=\"callout callout-danger\"><strong>Piège.</strong> Faire signer un écrit au patient <span class=\"kw-ci\">n'est pas une preuve de l'information</span> et peut être contre-productif (allure de décharge de responsabilité) — il ne vaut que s'il corrobore un dialogue oral.</div>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Mineur</span></strong> : les parents sont destinataires de l'information ; le mineur en reçoit une, adaptée à son degré de maturité.</li>\n        <li><strong>Information renforcée + écrit</strong> : ex. <span class=\"kw-etio\">chirurgie esthétique</span> (information exhaustive, devis détaillé, délai de <span class=\"kw-chiffre\">≥ 15 jours</span> entre devis et intervention).</li>\n        <li><strong>Défaut d'information</strong> → <span class=\"kw-def\">perte de chance</span> d'avoir refusé + <span class=\"kw-def\">préjudice moral d'impréparation</span> ; engage la <strong>responsabilité civile</strong> (et ordinale), <span class=\"kw-ci\">pas une faute pénale</span> sauf exception (ex. IVG contre la volonté de la patiente).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 1 — Relation médecin-malade · 9 — Ethique et déontologie médicale</em></p>","frequence":4},{"id":"7-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître la définition et les conditions du recueil du consentement éclairé","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> Pour être <span class=\"kw-def\">licite</span>, un acte médical doit avoir un <strong>but médical</strong> et recueillir le <strong><span class=\"kw-def\">consentement éclairé</span></strong> du patient. C'est une <span class=\"kw-def\">codécision</span> (loi du <span class=\"kw-chiffre\">4 mars 2002</span>, art. L. 1111-4 CSP) : le médecin informe et préconise, le patient décide.</div>\n      <h4>Conditions de recueil du consentement</h4>\n      <ul>\n        <li><span class=\"kw-def\">Libre</span> (sans contrainte) et <span class=\"kw-def\">éclairé</span> (précédé d'une <span class=\"kw-def\">information</span> de qualité — un consentement fondé sur une information erronée ou lacunaire n'est <span class=\"kw-ci\">pas valide</span>).</li>\n        <li><strong>Préalable</strong> à toute démarche diagnostique, thérapeutique ou préventive ; <span class=\"kw-def\">révocable à tout moment</span>.</li>\n        <li><strong>Aucun formalisme</strong> en règle générale (recueil oral) — l'<span class=\"kw-def\">écrit</span> n'est exigé que dans des situations légalement codifiées.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Consentement écrit obligatoire — situations</th><th>Précisions</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Chirurgie esthétique</span></td><td>Produit destiné à rester dans le corps <span class=\"kw-chiffre\">&gt; 30 jours</span> (et non toute intervention sous AG)</td></tr>\n          <tr><td><span class=\"kw-etio\">Prélèvements</span></td><td>Sang sur <span class=\"kw-etio\">mineur</span> en vue d'un don ; prélèvement sur personne <span class=\"kw-etio\">mineure décédée</span> (écrit de <strong>chaque</strong> titulaire de l'autorité parentale)</td></tr>\n          <tr><td><span class=\"kw-etio\">IVG</span></td><td>IVG chirurgicale &lt; <span class=\"kw-chiffre\">14 SG (16 SA)</span> ; IVG hors établissement (femme enceinte, pas le géniteur)</td></tr>\n          <tr><td><span class=\"kw-etio\">Embryon / fœtus</span></td><td>Conservation, recherche, projet parental (les 2 membres du couple ou femme non mariée)</td></tr>\n          <tr><td><span class=\"kw-etio\">Stérilisation</span> contraceptive (majeur)</td><td>Délai de réflexion de <span class=\"kw-chiffre\">4 mois</span></td></tr>\n          <tr><td><span class=\"kw-etio\">PMA</span>, <span class=\"kw-imagerie\">IRM</span> fonctionnelle, <span class=\"kw-etio\">RIPH-1</span>, étude <span class=\"kw-etio\">génétique</span></td><td>Consentement écrit (couple, recherche, caractéristiques génétiques)</td></tr>\n        </tbody>\n      </table>\n      <h4>Cas particuliers du recueil</h4>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Mineur</span></strong> : son consentement est <strong>systématiquement recherché</strong> s'il est apte ; parents : <span class=\"kw-chiffre\">≥ 1</span> pour un acte usuel, <strong>les 2</strong> pour un acte non usuel. Le médecin peut <span class=\"kw-alerte\">passer outre le refus parental</span> en cas d'<span class=\"kw-clinique\">urgence</span>, de <span class=\"kw-alerte\">risque grave pour la santé</span>, ou si le mineur s'oppose à l'information de ses parents (PEC nécessaire).</li>\n        <li><strong><span class=\"kw-etio\">Majeur protégé</span></strong> : le consentement du majeur est toujours recherché ; assistance ou représentation par la personne chargée de la protection, selon la mesure et l'aptitude à consentir.</li>\n        <li><strong>Personne <span class=\"kw-clinique\">hors d'état d'exprimer sa volonté</span></strong> : la <span class=\"kw-def\">personne de confiance</span>, à défaut la famille ou les proches, sont <strong>consultés</strong> (<span class=\"kw-alerte\">≠ consentement</span> : le médecin peut agir malgré une opposition en cas de risque grave).</li>\n        <li><strong><span class=\"kw-def\">Injonction de soins</span></strong> (suivi socio-judiciaire) : le soin reste <strong>soumis au consentement</strong> du patient ; en cas de refus, la <span class=\"kw-alerte\">peine prononcée peut être mise à exécution</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 9 — Ethique et déontologie médicale · 15 — Soins psychiatriques sans consentement</em></p>","frequence":2},{"id":"7-6","rang":"A","rubrique":"Définition","titre":"Connaître les règles du partage des données de santé entre professionnels de santé (secret médical, partage des données de santé)","contenu":"<h4>Généralités</h4>\n      <div class=\"callout callout-info\"><strong>Contenu du secret.</strong> Le <span class=\"kw-def\">secret médical</span> couvre l'<strong>ensemble des informations</strong> venues à la connaissance du professionnel durant son exercice :\n        <ul>\n          <li>ce qui lui a été <strong>confié</strong> par le patient ;</li>\n          <li>ce qu'il a <strong>vu</strong>, <strong>entendu</strong>, <strong>compris</strong> ou <strong>déduit</strong>.</li>\n        </ul>\n        On attend une <span class=\"kw-def\">discrétion totale</span>. Il s'impose à <strong>tout intervenant</strong> du système de santé :\n        <ul>\n          <li>paramédicaux ;</li>\n          <li>étudiants ;</li>\n          <li>secrétaires ;</li>\n          <li>informaticiens…</li>\n        </ul>\n        Pas au seul médecin.\n      </div>\n      <div class=\"callout callout-danger\"><strong>Le patient ne peut pas délier le médecin du secret.</strong> Un médecin peut être condamné pour violation du secret <span class=\"kw-alerte\">même si le patient l'y avait autorisé</span> : le secret est institué dans l'intérêt du patient <strong>et</strong> de la santé publique.</div>\n\n      <h4>Vis-à-vis des proches</h4>\n      <ul>\n        <li>Secret <span class=\"kw-def\">absolu</span>, sauf :\n          <ul>\n            <li><span class=\"kw-etio\">parents d'un mineur</span> ;</li>\n            <li><span class=\"kw-etio\">tuteur d'un majeur</span> sous tutelle.</li>\n          </ul>\n        </li>\n        <li>En cas de <span class=\"kw-clinique\">diagnostic / pronostic grave</span> : la <strong>famille</strong> et la <span class=\"kw-def\">personne de confiance</span> reçoivent les informations nécessaires au soutien, <strong>sauf opposition du patient</strong>.</li>\n      </ul>\n\n      <h4>Responsabilités en cas de violation (cumulables)</h4>\n      <ol>\n        <li><span class=\"kw-alerte\">Délit pénal</span> jugé au tribunal correctionnel.</li>\n        <li>Sanction <span class=\"kw-def\">disciplinaire</span> par l'Ordre (jusqu'à la <strong>radiation</strong>).</li>\n        <li><span class=\"kw-def\">Responsabilité civile</span> pour les salariés (jusqu'au <strong>licenciement</strong>).</li>\n      </ol>\n\n      <h4>Certificat médical</h4>\n      <ul>\n        <li>Remis <span class=\"kw-def\">au patient</span> uniquement.</li>\n        <li><span class=\"kw-ci\">Ne jamais le remettre à un tiers</span>, y compris au conjoint ou à l'enfant.</li>\n      </ul>\n\n      <h4>Partage des données entre professionnels (secret partagé)</h4>\n      <table>\n        <thead><tr><th>Situation</th><th>Règle</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Même <span class=\"kw-def\">équipe de soins</span></strong></td><td>Informations <strong>réputées confiées à l'ensemble de l'équipe</strong> ; partage sans recueil de consentement, limité à ce qui est <strong>strictement nécessaire</strong> à la coordination / continuité des soins</td></tr>\n          <tr><td><strong>Hors équipe de soins</strong></td><td><span class=\"kw-alerte\">Consentement préalable du patient</span> requis (recueilli par tout moyen)</td></tr>\n          <tr><td><strong>Sans accord du patient</strong></td><td>Médecins en mission de contrôle :\n            <ul>\n              <li><span class=\"kw-def\">DIM</span> ;</li>\n              <li>médecin-conseil de la Sécurité sociale ;</li>\n              <li>médecin inspecteur de santé publique ;</li>\n              <li>médecin de l'<span class=\"kw-def\">ARS</span> ;</li>\n              <li>IGAS, HAS, CNIL.</li>\n            </ul>\n          </td></tr>\n        </tbody>\n      </table>\n\n      <h4>Principales dérogations légales</h4>\n      <p><em>Situations dans lesquelles le médecin est délié ponctuellement du secret.</em></p>\n      <table>\n        <thead><tr><th>Domaine</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Déclarations obligatoires</span></td><td>\n            <ul>\n              <li><span class=\"kw-etio\">Naissances</span> (&lt; <span class=\"kw-chiffre\">5 j</span>) ;</li>\n              <li><span class=\"kw-etio\">décès</span> ;</li>\n              <li><span class=\"kw-def\">MDO</span> (données anonymisées → ANSP) ;</li>\n              <li><span class=\"kw-etio\">infections nosocomiales</span> graves et <span class=\"kw-etio\">EIG</span> (→ DG ARS).</li>\n            </ul>\n          </td></tr>\n          <tr><td><span class=\"kw-def\">CPAM</span></td><td>\n            <ul>\n              <li>Au <strong>service médical</strong> ✅ ;</li>\n              <li><span class=\"kw-ci\">jamais au service administratif ni à l'employeur</span>.</li>\n            </ul>\n          </td></tr>\n          <tr><td>Personnes <span class=\"kw-etio\">vulnérables</span></td><td>\n            <ul>\n              <li>Certificat circonstancié pour <span class=\"kw-etio\">majeur à protéger</span> ;</li>\n              <li><span class=\"kw-alerte\">signalement des maltraitances</span> (mineur, personne vulnérable) sans accord requis.</li>\n            </ul>\n          </td></tr>\n          <tr><td><span class=\"kw-etio\">Psychiatrie</span> sous contrainte</td><td>\n            <ul>\n              <li>1 ou 2 certificats nominatifs sans consentement ;</li>\n              <li>commission départementale.</li>\n            </ul>\n          </td></tr>\n          <tr><td><span class=\"kw-etio\">Toxicomanie</span> / <span class=\"kw-etio\">dopage</span></td><td>\n            <ul>\n              <li>Toxicomanie : information de l'<span class=\"kw-def\">ARS</span> (PEC, non répressif) ;</li>\n              <li>dopage : antenne médicale de prévention du dopage.</li>\n            </ul>\n          </td></tr>\n          <tr><td><span class=\"kw-etio\">Justice</span></td><td>\n            <ul>\n              <li><span class=\"kw-def\">Réquisition</span> / <span class=\"kw-def\">saisie</span> ;</li>\n              <li>crime ou délit qu'on peut encore empêcher ;</li>\n              <li>détention / intention d'acquérir une <span class=\"kw-etio\">arme à feu</span> (info au préfet).</li>\n            </ul>\n          </td></tr>\n          <tr><td><span class=\"kw-etio\">Violences</span> sur majeur non protégé</td><td>Signalement au procureur <strong>avec l'accord</strong> de la victime</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Pas de dérogation</strong> :\n        <ul>\n          <li><span class=\"kw-ci\">signaler une personne alcoolique</span> ;</li>\n          <li>remettre un certificat à une <span class=\"kw-ci\">compagnie d'assurance</span> (ni à son médecin-conseil).</li>\n        </ul>\n        Les informations passent par le <strong>patient</strong>, qui décide de ce qu'il transmet.\n      </div>\n\n      <h4>Cas particuliers</h4>\n      <ul>\n        <li><strong>Santé au travail</strong> :\n          <ul>\n            <li><span class=\"kw-alerte\">pas de secret partagé</span> entre médecin traitant et médecin du travail ;</li>\n            <li>le salarié fait l'intermédiaire ;</li>\n            <li>l'employeur ne reçoit que l'<span class=\"kw-def\">aptitude / inaptitude</span>.</li>\n          </ul>\n        </li>\n        <li><strong>Expert judiciaire</strong> :\n          <ul>\n            <li>matière <span class=\"kw-def\">civile</span> : accès au dossier <strong>via le patient</strong> ;</li>\n            <li>matière <span class=\"kw-def\">pénale</span> : <span class=\"kw-def\">saisie</span> ordonnée par le juge d'instruction.</li>\n          </ul>\n        </li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 13 — Certificats médicaux · 15 — Soins psychiatriques sans consentement · 80 — Dopage</em></p>","frequence":8},{"id":"7-7","rang":"A","rubrique":"Définition","titre":"Savoir définir le contenu d’un dossier médical, connaître les obligations quant à la tenue d’un dossier médical","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> Le <span class=\"kw-def\">dossier médical</span> est un document <strong>sécurisé et pérenne</strong> regroupant, pour chaque patient, l'ensemble des informations le concernant. Sa <span class=\"kw-def\">création est obligatoire</span> pour tout patient (établissements publics et privés, médecins libéraux).</div>\n      <div class=\"callout callout-warn\"><strong>Pas de propriétaire au sens strict.</strong> Le <span class=\"kw-etio\">patient</span> a un <strong>pouvoir de contrôle</strong> sur ses données mais n'en est pas propriétaire ; le <span class=\"kw-etio\">médecin / l'établissement</span> en est le <strong>dépositaire</strong>, responsable de sa <span class=\"kw-def\">conservation</span>.</div>\n      <p><strong>Finalités de la tenue</strong> : continuité et qualité des soins · partage entre acteurs · droit d'accès du patient · <span class=\"kw-alerte\">preuve en cas de recherche de responsabilité</span> (défense du médecin / de l'établissement).</p>\n      <div class=\"callout callout-info\"><strong>Base légale.</strong> Article <span class=\"kw-def\">R. 1112-2</span> CSP : les informations du dossier hospitalier se classent en <strong>3 catégories</strong> : ① informations formalisées <span class=\"kw-clinique\">durant le séjour</span> (consultations, urgences, admission, CR opératoires…) ; ② informations formalisées à la <span class=\"kw-clinique\">fin du séjour</span> (lettre de liaison, prescriptions de sortie) ; ③ informations recueillies <span class=\"kw-alerte\">auprès de tiers</span> ou les concernant (<span class=\"kw-ci\">non communicables au patient</span>).</div>\n      <table >\n        <thead><tr><th>Délai de conservation</th><th>Règle</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cas général</strong></td><td><span class=\"kw-chiffre\">20 ans</span> à compter de la dernière prise en charge</td></tr>\n          <tr><td><strong>Enfant &lt;<span class=\"kw-chiffre\"> 8 ans</span></strong></td><td>On ne compte pas les <span class=\"kw-chiffre\">8 premières années</span> → conservation reportée aux <span class=\"kw-chiffre\">28 ans</span> du patient</td></tr>\n          <tr><td><strong>Décès du patient</strong></td><td><span class=\"kw-chiffre\">10 ans</span> à compter de la date du décès</td></tr>\n          <tr><td><strong>Cas particuliers</strong></td><td><span class=\"kw-chiffre\">30 ans</span> : caractéristiques génétiques, identification par empreintes génétiques, dossiers de transfusion</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Contenu</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Informations formalisées</span> (communicables)</td><td>Lettre de liaison ; prescriptions ; motif / ATCD / conclusions cliniques ; examens (imagerie, biologie) ; dossier d'anesthésie ; CR opératoire ; <span class=\"kw-def\">consentement écrit</span> ; actes transfusionnels ; CR de <span class=\"kw-def\">RCP</span> ; mention des <span class=\"kw-def\">directives anticipées</span> et de la <span class=\"kw-def\">personne de confiance</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Informations NON communicables</span></td><td>Informations recueillies auprès de <span class=\"kw-etio\">tiers</span> (ou les concernant) ; <span class=\"kw-def\">notes personnelles</span> du professionnel (subjectives, non formalisées)</td></tr>\n        </tbody>\n      </table>\n      <h4>Accès et délais de communication</h4>\n      <ul>\n        <li><strong>Accès direct</strong> : <span class=\"kw-etio\">patient majeur non protégé</span>, <span class=\"kw-etio\">parents d'un mineur</span>, <span class=\"kw-etio\">tuteur / curateur</span>, équipe de soins. En cas de <span class=\"kw-etio\">décès</span> : <span class=\"kw-etio\">ayant droit / concubin / partenaire de PACS</span>, sous conditions (motif : connaître les causes de la mort, défendre la mémoire du défunt, faire valoir ses droits ; absence d'opposition du défunt).</li>\n        <li><strong>Délais</strong> : accès au plus tôt après <span class=\"kw-chiffre\">48 h</span> ; communication sous <span class=\"kw-chiffre\">8 jours</span> (données &lt; <span class=\"kw-chiffre\">5 ans</span>) ou <span class=\"kw-chiffre\">2 mois</span> (données &gt; <span class=\"kw-chiffre\">5 ans</span>). Consultation sur place gratuite ; frais de copie / d'envoi à la charge du patient.</li>\n        <li><strong>Dossier informatisé (DPI)</strong> : déclaration à la <span class=\"kw-def\">CNIL</span>, information du patient ; même valeur probante que le papier.</li>\n      </ul>\n      <div class=\"obj-callout success\"><strong>Dossier médical partagé (DMP).</strong> Géré par la <span class=\"kw-def\">CNAM</span>, gratuit, sur <em>monespacesante.fr</em> ; création sur <span class=\"kw-def\">consentement exprès</span> du patient (titulaire). Le <span class=\"kw-etio\">médecin traitant</span> a accès à la <strong>totalité</strong> du DMP ; <span class=\"kw-ci\">médecins du travail et assureurs n'y ont pas accès</span>. Conservé <span class=\"kw-chiffre\">10 ans</span> après clôture.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 13 — Certificats médicaux · 15 — Soins psychiatriques sans consentement</em></p>","frequence":2},{"id":"7-8","rang":"A","rubrique":"Définition","titre":"Connaître les définitions de l’autonomie","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> Le principe d'<span class=\"kw-def\">autonomie</span> fonde la <span class=\"kw-def\">liberté</span> : il reconnaît à toute personne la capacité de <strong>juger ce qui est juste ou bon pour elle</strong> et de participer aux décisions qui la concernent (<span class=\"kw-def\">autodétermination</span>).</div>\n      <ul>\n        <li>L'un des <strong>quatre principes</strong> de l'éthique médicale : <span class=\"kw-def\">bienfaisance</span>, <span class=\"kw-def\">non-malfaisance</span>, respect de l'<span class=\"kw-def\">autonomie</span>, <span class=\"kw-def\">justice</span>.</li>\n        <li><span class=\"kw-alerte\">Rupture</span> avec le modèle <span class=\"kw-def\">paternaliste</span> (décisions prises sans l'aval ni l'information du patient) : depuis les années <span class=\"kw-chiffre\">1970</span>, on associe le patient aux choix → la décision devient une <strong><span class=\"kw-def\">codécision</span></strong>.</li>\n        <li>En pratique, le respect de l'autonomie impose un <strong>devoir d'<span class=\"kw-def\">information</span> préalable</strong> au recueil du <span class=\"kw-def\">consentement</span> : un consentement non précédé d'une information de qualité n'est pas légitime.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Limites de l'autonomie.</strong> Elle n'est pas un absolu : <span class=\"kw-clinique\">grande vulnérabilité</span>, <span class=\"kw-clinique\">urgence</span>, <span class=\"kw-alerte\">perte d'autonomie psychique liée à la maladie</span>, ou revendications non conciliables avec les valeurs et l'organisation du système de santé.</div>\n      <p class=\"obj-source\"><em>Distillé depuis le Collège de Médecine légale / éthique (items 7 et 9).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 9 — Ethique et déontologie médicale · 1 — Relation médecin-malade</em></p>","frequence":0},{"id":"7-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître la définition du refus de soin","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> Le <span class=\"kw-def\">refus de soin</span> est le droit du patient de <strong>refuser un <span class=\"kw-def\">traitement</span> ou un <span class=\"kw-def\">acte</span></strong>, <span class=\"kw-alerte\">même lorsque sa vie est en danger</span>, dès lors qu'il est en état d'exprimer sa <span class=\"kw-def\">volonté</span> — après que le médecin l'a <strong>informé des <span class=\"kw-def\">conséquences</span></strong> de son choix et de leur gravité (art. L. 1111-4 CSP).</div>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Pronostic vital non engagé</span></strong></td><td>Respecter le choix ; information <strong>exhaustive</strong> sur les risques, répéter l'entretien, <strong>tracer dans le dossier</strong>, informer la <span class=\"kw-def\">personne de confiance</span> / la famille (sauf opposition), proposer un <span class=\"kw-def\">document de sortie contre avis médical</span> (≠ décharge de responsabilité). Maintenir une PEC <span class=\"kw-def\">«&nbsp;dégradée&nbsp;» mais adaptée</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Pronostic vital engagé</span></strong></td><td>Pas de poursuite pour <span class=\"kw-def\">non-assistance</span> (le refus est une cause d'exonération) ; agir <strong>contre</strong> la volonté clairement exprimée exposerait à une condamnation pour <span class=\"kw-alerte\">violences volontaires</span>. Ex. <span class=\"kw-etio\">Témoins de Jéhovah</span> / transfusion.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Principe.</strong> Respecter le <span class=\"kw-def\">consentement</span> — et donc le <span class=\"kw-def\">choix du patient</span> — est un <strong>devoir plus absolu</strong> pour le médecin que celui de sauver la vie. Le refus doit être <span class=\"kw-def\">réitéré</span> et <span class=\"kw-def\">tracé dans le dossier</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 141 — Soins palliatifs 3 - sédation - fin de vie · 9 — Ethique et déontologie médicale</em></p>","frequence":0},{"id":"7-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître la définition, les conditions de recueil, de validité et les situations dans lesquelles consulter les directives anticipées","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> Les <span class=\"kw-def\">directives anticipées</span> expriment, par écrit, les <strong>souhaits d'une personne relatifs à sa fin de vie</strong> (poursuite, limitation ou arrêt des traitements) pour le cas où elle serait <span class=\"kw-clinique\">hors d'état d'exprimer sa volonté</span>. Loi du <span class=\"kw-chiffre\">22 avril 2005</span>, renforcées par la loi <span class=\"kw-def\">Claeys-Leonetti</span> du <span class=\"kw-chiffre\">2 février 2016</span>.</div>\n      <ul>\n        <li><strong>Recueil</strong> : toute personne <span class=\"kw-etio\">majeure</span> peut les rédiger librement, par <span class=\"kw-def\">écrit</span> ; un <span class=\"kw-etio\">majeur protégé</span> avec l'autorisation du juge. <span class=\"kw-def\">Révocables et modifiables à tout moment</span>.</li>\n        <li><strong>Validité</strong> : <span class=\"kw-def\">durée illimitée</span> (depuis 2016), tant qu'elles ne sont pas modifiées ; elles sont <strong><span class=\"kw-alerte\">opposables au médecin</span></strong>.</li>\n        <li><strong>Conservation</strong> : par tout moyen les rendant aisément accessibles — auteur, <span class=\"kw-def\">personne de confiance</span>, famille, dossier du médecin de ville, dossier hospitalier, <span class=\"kw-def\">DMP</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Exceptions à leur application</strong> (le médecin peut s'en écarter) : <span class=\"kw-clinique\">urgence vitale</span>, le temps d'une évaluation complète ; ou directives <span class=\"kw-alerte\">manifestement inappropriées</span> / non conformes à la situation médicale → après <span class=\"kw-def\">procédure collégiale</span>.</div>\n      <div class=\"obj-callout success\"><strong>Quand les consulter ?</strong> Lors de toute décision de <span class=\"kw-def\">limitation ou d'arrêt de traitement</span> (refus de l'<span class=\"kw-def\">obstination déraisonnable</span>) chez un patient hors d'état de s'exprimer. <strong>Hiérarchie de la volonté</strong> : <span class=\"kw-def\">directives anticipées</span> &gt; <span class=\"kw-def\">personne de confiance</span> &gt; famille / proches.</div>\n      <p class=\"obj-source\"><em>Distillé depuis le Collège de Médecine légale (item 7).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 141 — Soins palliatifs 3 - sédation - fin de vie · 140 — Soins palliatifs 2 - accompagnement de la personne et de son entourage</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"http://monespacesante.fr","label":"monespacesante.fr"}],"cards":[{"i":"2b913716f0f9","n":7,"o":"7-1","u":"Définition","t":"Connaître les droits individuels des patients","q":"Quelle loi française est considérée comme le socle des droits individuels du patient et quelle est sa philosophie principale ?","a":"<p>La loi du <strong>4 mars 2002</strong>, dite loi Kouchner, est le socle des droits individuels du patient. Sa philosophie principale est de faire de l'acte de soin une <strong>codécision</strong>, où le médecin informe et préconise, et le patient décide.</p>"},{"i":"98349a737e0d","n":7,"o":"7-1","u":"Définition","t":"Connaître les droits individuels des patients","q":"Quels sont les droits individuels fondamentaux des patients reconnus par la loi de 2002 ?","a":"<ul><li>Droit à l'<strong>information</strong> « loyale, claire et appropriée » sur son état et les actes proposés (le secret médical n'est pas opposable au patient lui-même).</li><li>Droit au <strong>consentement libre et éclairé</strong>, préalable à tout acte.</li><li>Droit d'accès direct à son <strong>dossier médical</strong> (art. L. 1111-7 CSP).</li><li>Droit au respect de la <strong>vie privée</strong> et au contrôle de ses données de santé.</li><li>Droit de désigner une <strong>personne de confiance</strong> (art. L. 1111-6 CSP).</li><li>Droit de <strong>refuser les soins</strong>, même au péril de sa vie, après information sur les conséquences.</li></ul>"},{"i":"d27904b9cd7e","n":7,"o":"7-1","u":"Définition","t":"Connaître les droits individuels des patients","q":"Quels sont les droits spécifiques du patient en fin de vie et quelle est la hiérarchie de la volonté selon la loi de 2016 ?","a":"<p>En fin de vie, les patients ont les droits suivants :</p><ul><li>Droit au refus de l'<strong>obstination déraisonnable</strong>.</li><li>Droit aux <strong>directives anticipées</strong>.</li><li>Droit à la <strong>sédation profonde et continue</strong> (lois du 22 avril 2005 et du 2 février 2016).</li></ul><p>La hiérarchie de la volonté (loi 2016) est : <strong>directives anticipées > témoignage de la personne de confiance > témoignage de la famille / des proches</strong>.</p>"},{"i":"010ef9ad4812","n":7,"o":"7-4","u":"Définition","t":"Connaître les grands principes de l’information médicale","q":"Quelles sont les exceptions au devoir d'information médicale ?","a":"<ul><li>L'<strong>urgence vitale</strong> chez un patient non en état de recevoir l'information.</li><li>Le <strong>refus du patient</strong> d'être informé (sauf si des tiers sont exposés à un risque de transmission, par exemple dans le cas du VIH).</li></ul>"},{"i":"0f66e01f89e7","n":7,"o":"7-4","u":"Définition","t":"Connaître les grands principes de l’information médicale","q":"Quels types de risques doivent impérativement être révélés au patient dans le cadre de l'information médicale ?","a":"<p>Il faut révéler les risques <strong>fréquents ET graves</strong>, même exceptionnels. On entend par « graves » un risque de <strong>décès</strong>, d'<strong>invalidité</strong> ou des <strong>risques esthétiques importants</strong>.</p>"},{"i":"31a33257ebda","n":7,"o":"7-4","u":"Définition","t":"Connaître les grands principes de l’information médicale","q":"Quel est le piège classique concernant la preuve de l'information médicale et la signature d'un document ?","a":"<p>Faire signer un écrit au patient <strong>n'est pas une preuve suffisante</strong> de l'information et peut être contre-productif, donnant l'impression d'une décharge de responsabilité. L'écrit n'a de valeur que s'il corrobore un <strong>dialogue oral</strong> étayé.</p>"},{"i":"4752bda220d6","n":7,"o":"7-4","u":"Définition","t":"Connaître les grands principes de l’information médicale","q":"Quelles sont les conséquences d'un défaut d'information médicale pour le professionnel de santé ?","a":"<p>Un défaut d'information engage la <strong>responsabilité civile</strong> (et ordinale) du professionnel, entraînant une <strong>perte de chance</strong> pour le patient d'avoir refusé le soin et un <strong>préjudice moral d'impréparation</strong>. Il ne s'agit pas d'une faute pénale, sauf exception (ex: IVG contre la volonté de la patiente).</p>"},{"i":"6134c1c52efb","n":7,"o":"7-4","u":"Définition","t":"Connaître les grands principes de l’information médicale","q":"Quelle est la définition légale d'une information médicale valide en France ?","a":"<p>L'information médicale, condition d'un consentement éclairé, doit être <strong>loyale, claire et appropriée</strong>. Elle doit être explicite et adaptée au niveau de compréhension du patient, conformément à la <strong>loi du 4 mars 2002</strong>.</p>"},{"i":"9abc872cad30","n":7,"o":"7-4","u":"Définition","t":"Connaître les grands principes de l’information médicale","q":"Quels sont les éléments que doit couvrir l'information médicale fournie au patient ?","a":"<ul><li>L'<strong>état de santé</strong> du patient.</li><li>Le <strong>pronostic</strong>.</li><li>Les <strong>traitements et investigations proposés</strong>.</li><li>Les <strong>alternatives</strong> possibles.</li><li>Les <strong>risques encourus en cas de refus</strong> de soins.</li><li>Les <strong>conditions financières</strong> de la prise en charge.</li></ul>"},{"i":"ac9c2e073d56","n":7,"o":"7-4","u":"Définition","t":"Connaître les grands principes de l’information médicale","q":"Quelle est la forme privilégiée de l'information médicale et quel est le rôle de l'écrit ?","a":"<p>La forme privilégiée est <strong>orale</strong>, lors d'un entretien individuel préalable aux soins. L'écrit n'est qu'un <strong>complément</strong> à cet échange oral et ne le remplace pas.</p>"},{"i":"0308706c17b1","n":7,"o":"7-5","u":"Prise en charge","t":"Connaître la définition et les conditions du recueil du consentement éclairé","q":"Comment le consentement est-il recueilli pour une personne majeure protégée ou une personne hors d'état d'exprimer sa volonté ?","a":"<ul><li>Pour une <strong>personne majeure protégée</strong> : le <strong>consentement de la personne est toujours recherché</strong>. Elle est assistée ou représentée par la personne chargée de sa protection, selon la mesure et son aptitude à consentir.</li><li>Pour une <strong>personne hors d'état d'exprimer sa volonté</strong> : la <strong>personne de confiance</strong>, à défaut la famille ou les proches, sont consultés. Il ne s'agit pas d'un consentement mais d'un avis consultatif, le médecin pouvant agir malgré une opposition en cas de risque grave pour la santé du patient.</li></ul>"},{"i":"30af8364e6b6","n":7,"o":"7-5","u":"Prise en charge","t":"Connaître la définition et les conditions du recueil du consentement éclairé","q":"Dans quelles situations le consentement éclairé écrit est-il obligatoire en droit médical français ?","a":"<ul><li><strong>Chirurgie esthétique</strong>.</li><li>Produit destiné à rester dans le corps <strong>plus de 30 jours</strong>.</li><li><strong>Prélèvements</strong> : Sang sur mineur en vue d'un don ; prélèvement sur personne mineure décédée.</li><li><strong>IVG chirurgicale</strong> avant 14 semaines de grossesse (16 SA) et IVG hors établissement.</li><li>Actes sur <strong>embryon/fœtus</strong> (conservation, recherche, projet parental).</li><li><strong>Stérilisation contraceptive</strong> (pour un majeur).</li><li>Procédures telles que <strong>PMA, IRM fonctionnelle, RIPH-1, étude génétique</strong>.</li></ul>"},{"i":"8c473af6312c","n":7,"o":"7-5","u":"Prise en charge","t":"Connaître la définition et les conditions du recueil du consentement éclairé","q":"Quelles sont les conditions générales de recevabilité du consentement éclairé d'un patient ?","a":"<ul><li>Il doit être <strong>libre</strong> (sans contrainte).</li><li>Il doit être <strong>éclairé</strong>, c'est-à-dire précédé d'une information de qualité (un consentement fondé sur une information erronée ou lacunaire n'est pas valide).</li><li>Il est <strong>préalable</strong> à toute démarche diagnostique, thérapeutique ou préventive.</li><li>Il est <strong>révocable à tout moment</strong> par le patient.</li><li>Aucun formalisme n'est exigé en règle générale (recueil oral), sauf dans certaines situations légalement codifiées où l'écrit est obligatoire.</li></ul>"},{"i":"b9b0e28486c8","n":7,"o":"7-5","u":"Prise en charge","t":"Connaître la définition et les conditions du recueil du consentement éclairé","q":"Comment le consentement est-il recueilli pour un patient mineur, selon la législation française ?","a":"<ul><li>Le <strong>consentement du mineur est systématiquement recherché</strong> s'il est apte à exprimer sa volonté.</li><li>Pour les parents : le consentement d'<strong>au moins un parent</strong> est suffisant pour un <strong>acte usuel</strong>, mais le consentement des <strong>deux parents</strong> est requis pour un <strong>acte non usuel</strong>.</li><li>Le médecin peut passer outre le refus parental en cas d'<strong>urgence</strong>, de <strong>risque grave pour la santé du mineur</strong>, ou si le mineur s'oppose à l'information de ses parents et qu'une prise en charge est nécessaire.</li></ul>"},{"i":"df930493f0f1","n":7,"o":"7-5","u":"Prise en charge","t":"Connaître la définition et les conditions du recueil du consentement éclairé","q":"Quelle est la définition du consentement éclairé en droit médical français ?","a":"<p>En droit médical français, un acte médical, pour être licite, doit avoir un but médical et être précédé du recueil du consentement éclairé du patient. C'est une codécision issue de la <strong>loi du 4 mars 2002</strong> (article L. 1111-4 du Code de la Santé Publique) : le médecin informe et préconise, le patient décide.</p>"},{"i":"327198f94beb","n":7,"o":"7-6","u":"Définition","t":"Connaître les règles du partage des données de santé entre professionnels de santé (secret médical, partage des données de santé)","q":"Quelle est l'étendue du secret médical en France et à qui s'impose-t-il ?","a":"<p>Le secret médical couvre <strong>l'ensemble des informations</strong> venues à la connaissance du professionnel durant son exercice (ce qui lui a été confié, vu, entendu, compris ou déduit). Il s'impose à <strong>tout intervenant du système de santé</strong> : médecins, paramédicaux, étudiants, secrétaires, informaticiens, etc.</p>"},{"i":"615915a31dbf","n":7,"o":"7-6","u":"Définition","t":"Connaître les règles du partage des données de santé entre professionnels de santé (secret médical, partage des données de santé)","q":"Quelles sont les situations où un patient ne peut pas délier le médecin du secret médical et quelles sont les conséquences de sa violation ?","a":"<p>Le patient ne peut <strong>pas délier le médecin du secret</strong>, et un médecin peut être condamné pour sa violation même si le patient l'y a autorisé. Les responsabilités en cas de violation du secret sont <strong>cumulables</strong> :</p><ul><li><strong>Délit pénal</strong> (tribunal correctionnel).</li><li><strong>Sanction disciplinaire</strong> (Ordre, pouvant aller jusqu'à la radiation).</li><li><strong>Responsabilité civile</strong> pour les salariés (pouvant entraîner le licenciement).</li></ul>"},{"i":"c094e8e4ba4e","n":7,"o":"7-6","u":"Définition","t":"Connaître les règles du partage des données de santé entre professionnels de santé (secret médical, partage des données de santé)","q":"Quelles sont les principales dérogations légales au secret médical qu'un médecin doit connaître ?","a":"<ul><li><strong>Déclarations obligatoires</strong> (naissances, décès, MDO, infections nosocomiales graves, EIG).</li><li>Communication à la <strong>CPAM</strong> (uniquement au service médical).</li><li>Signalement des <strong>maltraitances</strong> (mineurs, personnes vulnérables) et certificat pour <strong>majeur à protéger</strong>.</li><li><strong>Psychiatrie sous contrainte</strong> (certificats nominatifs).</li><li><strong>Toxicomanie / dopage</strong> (information à l'ARS ou à l'antenne médicale).</li><li><strong>Justice</strong> (réquisition, crime/délit qu'on peut encore empêcher, détention/intention d'acquérir une arme à feu).</li><li>Signalement de <strong>violences sur majeur non protégé avec accord</strong> de la victime.</li></ul>"},{"i":"e0f409d01eb7","n":7,"o":"7-6","u":"Définition","t":"Connaître les règles du partage des données de santé entre professionnels de santé (secret médical, partage des données de santé)","q":"Quelles sont les règles du partage des données de santé entre professionnels lorsqu'ils appartiennent à la même équipe de soins ou non ?","a":"<ul><li><strong>Même équipe de soins</strong> : Les informations sont réputées confiées à l'ensemble de l'équipe. Le partage se fait <strong>sans recueil de consentement</strong> du patient, limité à ce qui est strictement nécessaire à la coordination et continuité des soins.</li><li><strong>Hors équipe de soins</strong> : Un <strong>consentement préalable du patient</strong> est requis (recueilli par tout moyen).</li></ul>"},{"i":"591b2e2bd5df","n":7,"o":"7-7","u":"Définition","t":"Savoir définir le contenu d’un dossier médical, connaître les obligations quant à la tenue d’un dossier médical","q":"Quels types d'informations sont communicables et incluses dans le contenu d'un dossier médical ?","a":"Les informations formalisées et communicables incluent notamment :<ul><li>Les <strong>lettres de liaison</strong>.</li><li>Les <strong>prescriptions</strong>.</li><li>Le motif de consultation, les <strong>antécédents</strong> et les conclusions cliniques.</li><li>Les résultats d'examens (imagerie, biologie).</li><li>Le dossier d'anesthésie et le <strong>compte-rendu opératoire</strong>.</li><li>Le <strong>consentement écrit</strong>.</li><li>Les actes transfusionnels.</li><li>Les comptes-rendus de <strong>RCP</strong> (Réunion de Concertation Pluridisciplinaire).</li><li>La mention des <strong>directives anticipées</strong> et de la <strong>personne de confiance</strong>.</li></ul>"},{"i":"896a01f839af","n":7,"o":"7-7","u":"Définition","t":"Savoir définir le contenu d’un dossier médical, connaître les obligations quant à la tenue d’un dossier médical","q":"Quel est le délai de conservation général d'un dossier médical en France ?","a":"<ul><li><strong>Cas général</strong> : <strong>20 ans</strong> à compter de la date de la dernière prise en charge.</li><li><strong>Enfant de moins de 8 ans</strong> : Le délai de 20 ans commence à courir à partir des 8 ans de l'enfant, reportant la conservation jusqu'à ses <strong>28 ans</strong>.</li><li><strong>Décès du patient</strong> : <strong>10 ans</strong> à compter de la date du décès.</li><li><strong>Cas particuliers</strong> : <strong>30 ans</strong> pour les dossiers incluant des caractéristiques génétiques, des empreintes génétiques ou des actes transfusionnels.</li></ul>"},{"i":"a7e62c92cc60","n":7,"o":"7-7","u":"Définition","t":"Savoir définir le contenu d’un dossier médical, connaître les obligations quant à la tenue d’un dossier médical","q":"Quels types d'informations ne sont PAS communicables au patient ou à ses ayants droit, même si elles se trouvent dans un dossier médical ?","a":"<p>Les informations <strong>non formalisées</strong> ou <strong>non objectives</strong> ne sont pas communicables. Cela inclut :</p><ul><li>Toutes les informations recueillies auprès de <strong>tiers</strong> ou les concernant directement.</li><li>Les <strong>notes personnelles</strong> du professionnel, considérées comme subjectives et non formelles.</li></ul>"},{"i":"e1dec54b5013","n":7,"o":"7-7","u":"Définition","t":"Savoir définir le contenu d’un dossier médical, connaître les obligations quant à la tenue d’un dossier médical","q":"Quelles sont les principales finalités de la tenue d'un dossier médical en France ?","a":"<ul><li>Assurer la <strong>continuité et la qualité des soins</strong>.</li><li>Permettre le <strong>partage d'informations</strong> entre les différents acteurs de santé.</li><li>Garantir le <strong>droit d'accès du patient</strong> à ses propres données.</li><li>Servir de <strong>preuve</strong> en cas de recherche de responsabilité, protégeant ainsi le médecin ou l'établissement.</li></ul>"},{"i":"f4282a8e57bf","n":7,"o":"7-7","u":"Définition","t":"Savoir définir le contenu d’un dossier médical, connaître les obligations quant à la tenue d’un dossier médical","q":"Qu'est-ce que le dossier médical, selon la réglementation française ?","a":"<p>En France, le dossier médical est un document <strong>sécurisé et pérenne</strong> regroupant l'ensemble des informations concernant un patient. Sa création est <strong>obligatoire</strong> pour tout patient pris en charge, que ce soit en établissement de santé public ou privé, ou par un médecin libéral. Le patient en est le contrôleur mais n'en est pas propriétaire, le médecin ou l'établissement en est le <strong>dépositaire</strong>.</p>"},{"i":"07199d9436d2","n":7,"o":"7-8","u":"Définition","t":"Connaître les définitions de l’autonomie","q":"Dans quelles situations le principe d'autonomie du patient peut-il être limité ?","a":"<p>Le principe d'autonomie n'est <strong>pas absolu</strong> et peut être limité dans les situations suivantes :</p><ul><li><strong>Grande vulnérabilité</strong> du patient.</li><li>Situations d'<strong>urgence</strong>.</li><li>Perte d'autonomie psychique liée à la <strong>maladie</strong>.</li><li>Revendications non conciliables avec les <strong>valeurs et l'organisation du système de santé</strong>.</li></ul>"},{"i":"0bb13c5a4c62","n":7,"o":"7-8","u":"Définition","t":"Connaître les définitions de l’autonomie","q":"Comment le principe d'autonomie se positionne-t-il par rapport aux autres principes fondamentaux de l'éthique médicale ?","a":"<p>L'autonomie est l'un des <strong>quatre principes fondamentaux</strong> de l'éthique médicale, aux côtés de la <strong>bienfaisance</strong>, de la <strong>non-malfaisance</strong> et de la <strong>justice</strong>.</p>"},{"i":"957bbb585757","n":7,"o":"7-8","u":"Définition","t":"Connaître les définitions de l’autonomie","q":"Quelle est la définition du principe d'autonomie du patient en éthique médicale ?","a":"<p>Le principe d'autonomie reconnaît à toute personne la capacité de juger ce qui est juste ou bon pour elle et de participer aux décisions qui la concernent. C'est le principe d'<strong>autodétermination</strong> du patient.</p>"},{"i":"e84c32bc055f","n":7,"o":"7-8","u":"Définition","t":"Connaître les définitions de l’autonomie","q":"Quel est l'impact du principe d'autonomie sur la relation médecin-patient et la prise de décision thérapeutique ?","a":"<p>Le principe d'autonomie a rompu avec le modèle <strong>paternaliste</strong> de la médecine. Il impose une <strong>codécision</strong>, où le patient est associé aux choix. Il implique un devoir d'<strong>information préalable</strong> pour un recueil du <strong>consentement</strong> légitime.</p>"},{"i":"41d8d28851cc","n":7,"o":"7-9","u":"Prise en charge","t":"Connaître la définition du refus de soin","q":"Quelle est la définition légale du refus de soin en droit français selon le Code de la Santé Publique ?","a":"<p>Le refus de soin est le <strong>droit du patient de refuser un traitement ou un acte</strong>, même lorsque sa vie est en danger, dès lors qu'il est en état d'exprimer sa volonté, après que le médecin l'a informé des conséquences de son choix et de leur gravité (article L. 1111-4 CSP).</p>"},{"i":"7cd2445a1e51","n":7,"o":"7-9","u":"Prise en charge","t":"Connaître la définition du refus de soin","q":"Comment le cadre légal protège-t-il le médecin en cas de refus de soin engageant le pronostic vital du patient ?","a":"<p>En cas de refus de soin clairement exprimé et tracé, le médecin ne peut pas être poursuivi pour <strong>non-assistance à personne en péril</strong>, car le refus du patient est une cause d'exonération. Agir contre la volonté clairement exprimée du patient exposerait le médecin à une condamnation pour <strong>violences volontaires</strong>.</p>"},{"i":"a5721cc3370c","n":7,"o":"7-9","u":"Prise en charge","t":"Connaître la définition du refus de soin","q":"Quelle est la conduite à tenir face à un refus de soin lorsque le pronostic vital du patient n'est pas engagé ?","a":"<ul><li><strong>Respecter le choix</strong> du patient.</li><li>Délivrer une <strong>information exhaustive</strong> sur les risques.</li><li><strong>Répéter l'entretien</strong> pour s'assurer de la constance de la décision.</li><li><strong>Tracer cette information et le refus dans le dossier médical</strong>.</li><li>Informer la <strong>personne de confiance ou la famille</strong> (sauf opposition du patient).</li><li>Proposer un <strong>document de sortie contre avis médical</strong> (qui n'est pas une décharge de responsabilité).</li><li>Maintenir une <strong>prise en charge « dégradée » mais adaptée</strong>.</li></ul>"}]};